// Audit log only: prints each machine's id when it is created and deleted. The check does not depend on it.
import { Sandbox } from "@tangle-network/sandbox";
const log = (m) => console.error(`${new Date().toISOString()} ${m}`);
const create = Sandbox.prototype.create;
Sandbox.prototype.create = async function (...args) {
  const box = await create.apply(this, args);
  log(`box created ${box.id}`);
  const del = box.delete.bind(box);
  box.delete = async (...a) => { const r = await del(...a); log(`box deleted ${box.id}`); return r; };
  return box;
};
